function validInt(n,max=1e9){return Number.isInteger(n)&&n>=0&&n<=max;}
function cleanName(value,fallback='خالد'){return String(value||'').replace(/[\u0000-\u001f\u007f<>]/g,'').trim().slice(0,24)||fallback;}
