const settings={...DEFAULT_PREFS,anime:defaultAnime()};if(s.questionHistoryResetAt!==undefined){if(!validInt(s.questionHistoryResetAt,1e14))throw Error('تاريخ دورة الأسئلة غير صالح.');settings.questionHistoryResetAt=s.questionHistoryResetAt;}if(s.anime!==undefined){settings.anime=validatedAnime(s.anime);}if(s.repetition!==undefined){if(!['recent','unseen','all'].includes(s.repetition))throw Error('سياسة تكرار الأسئلة غير صالحة.');settings.repetition=s.repetition;}for(const [k,allowed] of Object.entries({theme:['dark','light'],accent:['violet','gold'],motion:['none','subtle','full'],difficulty:['adaptive','1','2','3','4']})){if(!allowed.includes(s[k]))throw Error('أحد خيارات الإعدادات غير صالح.');settings[k]=s[k];}
for(const k of ['sound','music']){if(!validInt(s[k],100))throw Error('مستوى صوت غير صالح.');settings[k]=s[k];}
if(![15,20,30,45,60].includes(s.duration)||![90,100,115,130].includes(s.textSize))throw Error('إعداد عرض أو مؤقّت غير صالح.');settings.duration=s.duration;settings.textSize=s.textSize;
