if(s.results.some(r=>!questionMap.has(r.id)||typeof r.correct!=='boolean'||!validInt(r.points)||!validInt(r.player,3)||r.player>=s.players.length)||new Set(s.results.map(r=>r.id)).size!==s.results.length||s.results.some(r=>s.remaining.includes(r.id)))return null;
