if(s.current){const c=s.current;if(!questionMap.has(c.id)||!['answer','feedback'].includes(c.phase)||!['choice','text','boolean'].includes(c.format)||!Array.isArray(c.order)||c.order.length!==4||[0,1,2,3].some(x=>!c.order.includes(x))||!Array.isArray(c.eliminated)||c.eliminated.some(n=>!validInt(n,3))||!Array.isArray(c.used)||c.used.some(id=>!HELPERS.some(h=>h.id===id))||!Number.isFinite(c.remainingMs)||c.remainingMs<0||c.remainingMs>180000)return null;if(!Number.isFinite(c.base)||c.base<100||c.base>600||!['boolean'].includes(typeof c.timed)||typeof c.paused!=='boolean'||(c.deadline!==null&&(!Number.isFinite(c.deadline)||c.deadline<0||c.deadline>1e14))||!validInt(c.earned)||![null,true,false].includes(c.correct)||typeof c.text!=='string'||c.text.length>120||['hint','second','double','attempted'].some(k=>typeof c[k]!=='boolean'))return null;if(c.chosen!==null&&!validInt(c.chosen,3))return null;if(c.format==='boolean'&&!validInt(c.claimIndex,3))return null;}
