function load(allowRecovery=true){let raw=null;try{soloRecovery=localStorage.getItem(STORAGE_KEY+'-recovery');raw=localStorage.getItem(STORAGE_KEY);if(raw){const data=parseSafeJSON(raw,5000000),loaded=validateSave(data,true);prefs=loaded.prefs;progress=loaded.progress;session=loaded.session;if(allowRecovery&&data.session&&!session){soloRecovery=raw;try{localStorage.setItem(STORAGE_KEY+'-recovery',raw);}catch{soloRecoveryProtected=true;storageAvailable=false;}}if(session?.current?.phase==='answer'){const c=session.current;if(c.deadline)c.remainingMs=clamp(c.deadline-Date.now(),0,180000);c.paused=true;c.deadline=null;}}}catch{if(allowRecovery&&raw){soloRecovery=raw;try{localStorage.setItem(STORAGE_KEY+'-recovery',raw);}catch{soloRecoveryProtected=true;storageAvailable=false;}}storageAvailable=false;}}
function applyPrefs(){document.documentElement.dataset.theme=prefs.theme;document.querySelector('meta[name=theme-color]').content=prefs.theme==='light'?'#f2f3f8':'#090d1e';document.documentElement.dataset.accent=prefs.accent;document.documentElement.dataset.motion=prefs.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches?'none':prefs.motion;document.documentElement.style.setProperty('--text-scale',prefs.textSize/100);if(!prefs.music)stopMusic();}
