function soloEligibility(noSpoilers=false){const anime=prefs.anime||defaultAnime();return {spoilerProtection:noSpoilers||prefs.spoilers,anime:{selected:[...anime.selected],levels:Object.fromEntries(TeamEngine.FRANCHISES.map(f=>[f.id,noSpoilers?1:prefs.spoilers?(anime.levels[f.id]||1):3]))}};}
