function renderSetup(){if(!setup)return renderHome();const m=modeById(setup.mode),pool=eligible(setup.cats,setup.series,setup.mode),classic=setup.mode==='classic',series=[...new Set(QUESTION_BANK.filter(q=>q.category==='anime').map(q=>q.sub))];const valid=setup.cats.length>0&&(!classic||[2,4,6].includes(setup.cats.length))&&pool.length>=setup.players&&(!classic||setup.cats.every(id=>pool.filter(q=>q.category===id).length>=6));
return `${title('جهّز جولتك',m.name,m.desc)}<div class="setup-layout"><div class="setup-main"><div class="section-heading"><h2>اختر الفئات</h2><span class="pill">${setup.cats.length} محددة</span></div><p class="muted">${classic?'اختر 2 أو 4 أو 6 فئات. لكل فئة 6 خانات، من 100 إلى 600 نقطة.':'اختر فئة أو أكثر، وسنوازن الأسئلة بينها.'}</p><div class="category-grid">${CATEGORIES.map(c=>categoryCard(c,'toggle-category',setup.cats.includes(c.id))).join('')}</div><div class="panel stack"><div class="field"><label for="series">سلسلة الأنمي</label><select id="series" data-setup="series"><option value="all">كل السلاسل</option>${series.map(s=>`<option value="${esc(s)}" ${setup.series===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>${setup.mode!=='images'?`<div class="field"><label for="format">أسلوب الإجابة</label><select id="format" data-setup="format"><option value="choice" ${setup.format==='choice'?'selected':''}>4 اختيارات</option><option value="boolean" ${setup.format==='boolean'?'selected':''}>صح أم خطأ</option><option value="text" ${setup.format==='text'?'selected':''}>كتابة الإجابة</option></select><small class="muted">الكتابة تتجاهل التشكيل وأشكال الألف والمسافات، وتحافظ على الحروف المختلفة. يلزم اسم مقبول كما في الإجابة.</small></div>`:''}<label class="toggle-row"><span>حماية حرق أحداث الأنمي</span><input type="checkbox" data-pref="spoilers" ${prefs.spoilers?'checked':''}></label>${animePreferences()}${selectPref('repetition','تكرار الأسئلة',[['recent','تجنب الأسئلة الحديثة'],['unseen','تفضيل غير المشاهد'],['all','السماح بالجميع']])}</div>
${setup.players>1?`<div class="panel stack"><h2>أصدقاء التحدي</h2>${setup.mode==='tournament'?`<div class="field"><label for="player-count">عدد اللاعبين</label><select id="player-count" data-setup="players">${[2,3,4].map(n=>`<option ${setup.players===n?'selected':''}>${n}</option>`).join('')}</select></div>`:''}${setup.names.slice(0,setup.players).map((name,i)=>`<div class="field"><label for="player-${i}">اسم اللاعب ${i+1}</label><input id="player-${i}" data-player="${i}" value="${esc(name)}" maxlength="24" autocomplete="off"></div>`).join('')}<p class="muted">تُسلّمون الجهاز بالتناوب بعد كل سؤال. لكل لاعب رصيده الخاص من المساعدات.</p></div>`:''}</div><aside class="setup-summary panel stack"><span class="mode-icon" style="--accent:${m.color||'#eac57e'}">${icon(m.icon)}</span><h2>التحدي يبدأ باختيارك</h2><div class="summary-line"><span>الأسئلة المتاحة</span><strong>${pool.length}</strong></div><div class="summary-line"><span>اللاعبون</span><strong>${setup.players}</strong></div><div class="summary-line"><span>المؤقّت</span><strong>${setup.mode==='practice'?'بلا مؤقّت':setup.mode==='quick'?'12 ثانية':prefs.timer?`${prefs.duration} ثانية`:'معطّل'}</strong></div><p class="muted">${classic?'النقاط الأساسية هي قيمة الخانة. الدقة ثم السلسلة تصنع الفارق.':'النقاط: 100 × مستوى الصعوبة، مع مكافأة للسلسلة. المساعدات متاحة داخل الجولة.'}</p><button class="btn primary" data-action="start" ${!valid?'disabled':''}>لنبدأ اللعب ${icon('arrow')}</button><button class="btn secondary" data-action="nav" data-route="home">العودة للرئيسية</button><small class="muted">لا تتكرر الأسئلة داخل الجولة. عند نفاد فئة، ننتقل للأسئلة المتبقية.</small></aside></div>`;}
function soloRepeatRank(q){if(prefs.repetition==='all')return 0;const at=progress.seen[q.id];if(!at)return 0;return prefs.repetition==='unseen'?1:Date.now()-at<=30*86400000?2:1;}
function chooseBalanced(pool,count,seed,adaptive=false){const rng=seed===undefined?Math.random:seeded(seed),mixed=shuffled(pool,rng),chosen=[],cats=[...new Set(mixed.map(q=>q.category))];let cycle=shuffled(cats,rng);while(chosen.length<count&&mixed.length){for(const category of cycle){let list=mixed.filter(q=>q.category===category);if(!list.length)continue;list.sort((a,b)=>(soloRepeatRank(a)-soloRepeatRank(b)));const q=list[0];chosen.push(q);mixed.splice(mixed.indexOf(q),1);if(chosen.length>=count)break;}}return chosen;}
function startGame(mode=setup?.mode,daily=false){
const cats=daily?CATEGORIES.map(c=>c.id):setup.cats,series=daily?'all':setup.series;let pool=daily?dailyPool():eligible(cats,series,mode);if(!pool.length){toast('لا توجد أسئلة تطابق هذه الفلاتر. غيّر الفئات أو السلسلة.');return;}
if(mode==='classic'&&![2,4,6].includes(cats.length)){toast('اختر 2 أو 4 أو 6 فئات للوحة الكلاسيكية.');return;}
const players=Array.from({length:daily?1:setup.players},(_,i)=>({name:cleanName(setup.names[i],`اللاعب ${i+1}`),score:0,correct:0,answered:0,streak:0,lives:3}));
const target=mode==='classic'?cats.length*6:mode==='quick'||mode==='duo'?12:mode==='tournament'?Math.floor(16/players.length)*players.length:mode==='survival'?pool.length:mode==='practice'?Math.min(20,pool.length):10;
if(mode==='classic'&&cats.some(id=>pool.filter(q=>q.category===id).length<6)){toast('تحتاج كل فئة إلى 6 أسئلة بعد الفلترة. غيّر السلسلة أو الفئات.');return;}
if(pool.length<players.length){toast('اختر فئات أوسع لتوفير سؤال واحد على الأقل لكل لاعب.');return;}
const date=localDate();const chosen=daily?chooseDaily(pool,Math.min(10,pool.length),hash(date+'seen-v1')):chooseBalanced(pool,pool.length);if(daily&&chosen.length<10)toast(`التحدي اليومي يضم ${chosen.length} من الأسئلة المتاحة بعد الفلترة.`);
session={schema:1,id:String(Date.now()),mode,cats:[...cats],players,turn:0,remaining:chosen.map(q=>q.id),target:daily?chosen.length:Math.min(target,pool.length),total:daily?chosen.length:Math.min(target,pool.length),board:[],results:[],bags:players.map(()=>({fifty:1,time:1,skip:1,hint:2,second:1,double:1})),current:null,status:'active',date,format:daily?'choice':setup.format,created:Date.now(),handoff:false,finished:false};
if(players.length>1){session.target=Math.floor(session.target/players.length)*players.length;session.total=session.target;if(!session.target){toast('اختر فئات أوسع لتوفير سؤال واحد على الأقل لكل لاعب.');session=null;return;}}
if(mode==='classic'){const used=new Set();for(const category of cats){const cp=pool.filter(q=>q.category===category);if(cp.length<6){toast(`تحتاج فئة ${catById(category).name} إلى 6 أسئلة بعد الفلترة. غيّر الفلاتر.`);session=null;return;}for(let row=0;row<6;row++){const want=[1,1,2,2,3,4][row],available=shuffled(cp.filter(q=>!used.has(q.id)));available.sort((a,b)=>Math.abs(a.level-want)-Math.abs(b.level-want)||soloRepeatRank(a)-soloRepeatRank(b));const q=available[0];used.add(q.id);session.board.push({key:`${category}-${row}`,category,points:(row+1)*100,id:q.id,done:false});}}session.total=session.board.length;session.target=session.total;}else if(players.length>1)session.handoff=true;else nextQuestion();persist();navigate('play');}
function chooseDaily(pool,count,seed){const rng=seeded(seed),seen=new Set(),valid=pool.filter(q=>q&&!q.disabled&&!q.unavailable&&q.available!==false&&QUESTION_MAP.has(q.id)&&!seen.has(q.id)&&seen.add(q.id)).sort((a,b)=>a.id.localeCompare(b.id)),bycat=CATEGORIES.map(c=>shuffled(valid.filter(q=>q.category===c.id),rng)).filter(list=>list.length),out=[];const target=Math.min(Math.max(0,Math.floor(count)||0),valid.length);let cursor=bycat.length?seed%bycat.length:0;while(out.length<target&&bycat.some(list=>list.length)){const list=bycat[cursor%bycat.length];cursor++;if(list.length)out.push(list.pop());}return out;}
function nextQuestion(tile){if(!session||session.status!=='active')return;const s=session;const usable=s.remaining.filter(id=>QUESTION_MAP.has(id)&&!QUESTION_MAP.get(id).disabled);if(usable.length!==s.remaining.length){s.remaining=usable;if(s.mode==='daily'){s.target=s.total=s.results.length+usable.length;}toast('استُبعدت أسئلة غير متاحة؛ حُدّث عدد أسئلة الجولة.');}if(s.results.length>=s.target||(s.mode==='survival'&&s.players[0].lives<=0)){finishGame();return;}let id;if(tile){id=tile.id;}else if(s.mode==='daily'){id=s.remaining[0];}else{const p=s.players[s.turn],target=prefs.difficulty==='adaptive'?clamp(1+Math.floor(s.results.length/4)+(p.streak>=3?1:0)-(p.answered>=3&&p.correct/p.answered<.4?1:0),1,4):Number(prefs.difficulty),remaining=s.remaining.map(id=>QUESTION_MAP.get(id)),counts=Object.fromEntries(s.cats.map(c=>[c,s.results.filter(r=>QUESTION_MAP.get(r.id).category===c).length]));remaining.sort((a,b)=>(counts[a.category]||0)-(counts[b.category]||0)||Math.abs(a.level-target)-Math.abs(b.level-target)||soloRepeatRank(a)-soloRepeatRank(b));id=remaining[0]?.id;}
if(!id){finishGame();return;}s.remaining=s.remaining.filter(n=>n!==id);const q=QUESTION_MAP.get(id),timed=s.mode!=='practice'&&(s.mode==='quick'||prefs.timer),seconds=s.mode==='quick'?12:prefs.duration;const rng=s.mode==='daily'?seeded(hash(s.date+id)):Math.random;
s.current={id,order:shuffled([0,1,2,3],rng),phase:'answer',chosen:null,eliminated:[],used:[],hint:false,second:false,double:false,attempted:false,format:s.format||'choice',claimIndex:Math.floor(rng()*4),deadline:timed?Date.now()+seconds*1000:null,remainingMs:timed?seconds*1000:0,timed,paused:false,tile:tile?.key||null,base:tile?.points||q.level*100,correct:null,earned:0,outcome:null,text:''};persist();}
function pauseSession(save=true){if(session?.current?.phase==='answer'){const c=session.current;if(c.deadline)c.remainingMs=Math.max(0,c.deadline-Date.now());c.deadline=null;c.paused=true;if(save)persist();}clearInterval(timerHandle);timerHandle=null;}
