function resumeGame(){if(!session)return;if(session.status==='done'){navigate('result');return;}navigate('play');}
function scoreStrip(){return `<div class="score-strip">${session.players.map((p,i)=>`<div class="player-score ${session.turn===i?'active':''}"><span class="player-dot">${i+1}</span><div><small>${esc(p.name)} ${session.turn===i?'· دورك':''}</small><strong>${num(p.score)} <span>نقطة</span></strong></div>${session.mode==='survival'?`<span class="lives" aria-label="${p.lives} قلوب">${'♥'.repeat(clamp(Math.floor(Number(p.lives)||0),0,3))}${'♡'.repeat(3-clamp(Math.floor(Number(p.lives)||0),0,3))}</span>`:''}</div>`).join('')}<button class="icon-btn" data-action="nav" data-route="home" aria-label="حفظ الجولة والعودة للرئيسية">${icon('home')}</button></div>`;}
function soloStorageNotice(){return !storageAvailable?'<section class="inline-note warning" role="status"><span>الحفظ التلقائي غير متاح هنا؛ الجولة مستمرة في هذه الصفحة.</span><button class="btn secondary" data-action="solo-export">حفظ نسخة استئناف</button></section>':'';}
function renderPlay(){if(!session)return renderHome();if(session.status==='done')return renderResult();if(session.handoff)return `${soloStorageNotice()}${scoreStrip()}<div class="panel handoff empty-state"><span class="mode-icon">${icon('users')}</span><span class="eyebrow">مرّر الجهاز</span><h1>الدور الآن على ${esc(session.players[session.turn].name)}</h1><p class="muted">لا يبدأ المؤقّت حتى تضغط «أنا جاهز».</p><button class="btn primary" data-action="ready">أنا جاهز ${icon('play')}</button></div>`;if(!session.current)return soloStorageNotice()+renderBoard();return soloStorageNotice()+renderQuestion();}
function renderBoard(){const s=session;return `${scoreStrip()}${title('اختر سؤالك','لوحة التحدي',`أكملت ${s.results.length} من ${s.total} سؤالًا. الخانات الأعلى نقاطًا تكون أصعب غالبًا.`)}<div class="board-grid" style="--board-cols:${s.cats.length}">${s.cats.map(id=>{const c=catById(id);return `<section class="board-column" style="--accent:${c.color}"><div class="board-category"><div>${categoryArt(id)}</div><h2>${c.name}</h2></div>${s.board.filter(t=>t.category===id).map(t=>`<button class="point-tile ${t.done?'used':''}" data-action="tile" data-key="${esc(t.key)}" ${t.done?'disabled':''}>${t.done?icon('check'):t.points}<small>${t.done?'اكتمل':'نقطة'}</small></button>`).join('')}</section>`;}).join('')}</div><p class="footer-note">${storageAvailable?'تُحفظ اللوحة تلقائيًا. يمكنك العودة للرئيسية ومتابعتها لاحقًا.':'الجولة محفوظة في هذه الصفحة فقط. صدّر نسخة استئناف قبل إغلاقها.'}</p>`;}
