function hasActiveTrivia(){const team=window.SeenTeamUI?.match;return session?.status==='active'||!!(team&&team.state!=='MATCH_COMPLETE');}
function isAnswerProtected(id){if(session?.status==='active'&&(session.remaining.includes(id)||session.board.some(t=>t.id===id&&!t.done)||session.current?.id===id&&session.current.phase==='answer'))return true;const team=window.SeenTeamUI?.match;return !!(team&&team.state!=='MATCH_COMPLETE'&&team.board.some(t=>t.questionId===id&&!t.done)&&!(team.current?.questionId===id&&team.current.revealed));}
function questionAlt(q,revealed=false){return revealed?(VISUALS[q.image]?.alt||'دليل السؤال البصري'):'دليل بصري للسؤال؛ الوصف التعريفي متاح بعد الإجابة.';}
function safeHint(q){const hint=q.hint||'',normalized=normalizeArabic(hint),answers=[q.correctAnswer||q.options[q.answer],...(q.acceptedAnswers||[])].map(normalizeArabic).filter(Boolean);return hint&&!answers.some(a=>a.length===1?normalized.split(' ').includes(a):normalized.includes(a))?hint:'فكّر في سياق السؤال واستبعد الخيارات التي تنتمي إلى موضوع مختلف.';}
function safeURL(url){try{if(typeof url!=='string'||/[\u0000-\u0020\u007f]/.test(url))return '#';const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'#';}catch{return '#';}}
function startTicker(){const c=session?.current;if(!c||c.phase!=='answer'||c.paused||!c.timed)return;const tick=()=>{if(!session?.current||session.current!==c||c.phase!=='answer')return;const seconds=remainingSeconds(c),el=$('#timer-value');if(el){el.textContent=seconds;el.closest('.timer-ring').classList.toggle('urgent',seconds<=5);}if(seconds!==c.lastTick){if(seconds<=5&&seconds>0)sound('tick');if(seconds===10||seconds===5)$('#announcer').textContent=`بقيت ${seconds} ثوانٍ`;c.lastTick=seconds;}if(c.deadline&&Date.now()>=c.deadline){commitAnswer(null,'timeout');}};timerHandle=setInterval(tick,200);tick();}
function commitAnswer(value,outcome='answer'){
const s=session,c=s?.current;if(storageConflict||!s||!c||c.phase!=='answer'||c.paused)return;if(c.timed&&c.deadline&&Date.now()>=c.deadline&&outcome==='answer')outcome='timeout';
const q=QUESTION_MAP.get(c.id);let correct=false;
if(outcome==='answer'){if(c.format==='text'){const normalized=normalizeArabic(value);if(!normalized){toast('اكتب إجابتك أولًا.');return;}c.text=String(value).slice(0,120);correct=[q.options[q.answer],...(q.acceptedAnswers||[])].some(answer=>normalized===normalizeArabic(answer));}else{if(!Number.isInteger(value)||!((c.format==='boolean'?[0,1]:c.order).includes(value))||c.eliminated.includes(value))return;c.chosen=value;correct=c.format==='boolean'?Boolean(value)===(c.claimIndex===q.answer):value===q.answer;}
if(!correct&&c.second&&!c.attempted){c.attempted=true;if(c.format!=='text')c.eliminated.push(value);if(c.deadline)c.remainingMs=Math.max(0,c.deadline-Date.now());sound('wrong');toast('لديك فرصة ثانية. حاول مجددًا قبل انتهاء الوقت.');persist();render();return;}}
resolveQuestion(correct,outcome);
}
function resolveQuestion(correct,outcome){const s=session,c=s.current;if(c.phase!=='answer')return;clearInterval(timerHandle);c.remainingMs=c.deadline?Math.max(0,c.deadline-Date.now()):c.remainingMs;c.deadline=null;c.phase='feedback';c.correct=correct;c.outcome=outcome;const p=s.players[s.turn],q=QUESTION_MAP.get(c.id);p.answered++;p.streak=correct?p.streak+1:0;if(correct)p.correct++;if(!correct&&outcome!=='skip'&&s.mode==='survival')p.lives=Math.max(0,p.lives-1);const bonus=correct?Math.min(250,Math.floor((p.streak-1)/2)*50):0;c.earned=correct&&s.mode!=='practice'?(c.base+bonus)*(c.double?2:1):0;p.score+=c.earned;
s.results.push({id:q.id,correct,points:c.earned,player:s.turn});if(c.tile){const tile=s.board.find(t=>t.key===c.tile);if(tile)tile.done=true;}
if(correct)progress.solved[q.id]=true;progress.answers++;progress.correct+=Number(correct);progress.points+=c.earned;progress.xp+=correct?(s.mode==='practice'?5:10+q.level*5):2;progress.bestStreak=Math.max(progress.bestStreak,p.streak);if(correct&&q.image)progress.imageCorrect++;const stats=progress.category[q.category]||(progress.category[q.category]={answered:0,correct:0});stats.answered++;stats.correct+=Number(correct);progress.seen[q.id]=Date.now();progress.history.unshift({id:q.id,correct,at:Date.now()});progress.history=progress.history.slice(0,100);sound(correct?'correct':'wrong');if(correct&&p.streak%3===0)confetti();try{if(prefs.sound&&navigator.vibrate)navigator.vibrate(correct?25:[35,35,35]);}catch{}checkAchievements();persist();render();$('#main [data-action=next]')?.focus({preventScroll:true});$('#announcer').textContent=correct?`إجابة صحيحة. حصلت على ${c.earned} نقطة.`:`الإجابة الصحيحة: ${q.options[q.answer]}`;}
function helper(id){const s=session,c=s?.current;if(!c||c.phase!=='answer'||c.paused)return;if(c.timed&&c.deadline&&Date.now()>=c.deadline){commitAnswer(null,'timeout');return;}const bag=s.bags[s.turn],q=QUESTION_MAP.get(c.id);if(!bag[id]||c.used.includes(id))return;if(id==='time'&&!c.timed||id==='fifty'&&c.format!=='choice'||id==='double'&&s.mode==='practice')return;
if(id==='fifty'){const wrong=shuffled(c.order.filter(x=>x!==q.answer&&!c.eliminated.includes(x)));c.eliminated.push(...wrong.slice(0,Math.min(2,wrong.length)));}if(id==='time'){c.deadline+=15000;c.remainingMs+=15000;}if(id==='hint')c.hint=true;if(id==='second')c.second=true;if(id==='double')c.double=true;bag[id]--;c.used.push(id);if(id==='skip'){resolveQuestion(false,'skip');return;}persist();render();}
function goNext(){if(!session||session.current?.phase!=='feedback')return;session.current=null;if(session.results.length>=session.target||session.mode==='survival'&&session.players[0].lives<=0){finishGame();return;}session.turn=(session.turn+1)%session.players.length;if(session.players.length>1)session.handoff=true;else if(session.mode!=='classic')nextQuestion();persist();render();$('#question-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function finishGame(){const s=session;if(!s)return;s.status='done';s.current=null;if(!s.finished){s.finished=true;progress.games++;const first=s.players[0],win=s.players.length>1?first.score===Math.max(...s.players.map(p=>p.score)):first.correct/Math.max(1,first.answered)>=.6;if(s.mode!=='practice'){if(win)progress.wins++;else progress.losses++;}const total=s.players.reduce((sum,p)=>sum+p.score,0);progress.records[s.mode]=Math.max(progress.records[s.mode]||0,total);if(s.mode==='daily')progress.daily[s.date]={completed:true,score:total};checkAchievements();persist();confetti();}route='result';render();}
function renderResult(){if(!session)return renderHome();const s=session,sorted=[...s.players].sort((a,b)=>b.score-a.score),total=s.players.reduce((sum,p)=>sum+p.score,0),correct=s.results.filter(r=>r.correct).length,accuracy=Math.round(correct/Math.max(1,s.results.length)*100);return `<div class="result-hero panel"><span class="eyebrow">${modeById(s.mode).name} · اكتملت الجولة</span><div class="result-trophy">${icon('cup')}</div><h1>${s.players.length>1?(sorted.filter(p=>p.score===sorted[0].score).length>1?'تعادل جميل… وتحدٍ أجمل!':`الصدارة لـ ${esc(sorted[0].name)}`):accuracy>=60?'تألّقت معرفتك!':'كل جولة تزيدك معرفة'}</h1><div class="result-score">${num(total)} <small>نقطة</small></div><p class="muted">${correct} إجابة صحيحة من ${s.results.length} · دقة ${accuracy}%</p><div class="hero-actions"><button class="btn primary" data-action="replay">جولة جديدة ${icon('play')}</button><button class="btn secondary" data-action="nav" data-route="home">الرئيسية ${icon('home')}</button></div></div>${s.players.length>1?`<div class="panel stack"><h2>ترتيب الأصدقاء</h2>${sorted.map((p,i)=>`<div class="leaderboard-row"><span class="rank">${i+1}</span><strong>${esc(p.name)}</strong><span>${num(p.score)} نقطة · ${p.correct}/${p.answered} صحيحة</span></div>`).join('')}</div>`:''}<div class="section-heading"><h2>حصيلة المعرفة</h2><span class="muted">راجع التفسيرات والمصادر</span></div><div class="stack">${s.results.map((r,i)=>{const q=QUESTION_MAP.get(r.id);return `<details class="panel review-item"><summary><span class="review-status ${r.correct?'correct':'wrong'}">${icon(r.correct?'check':'close')}</span><span>${i+1}. ${esc(q.q)}</span><span class="muted">+${r.points}</span></summary><div><p><strong>${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p><p class="muted">${esc(q.source.title)} · ${esc(q.source.reference)}</p><a class="source-link" href="${esc(safeURL(q.source.url))}" target="_blank" rel="noopener noreferrer">فتح المرجع</a></div></details>`;}).join('')}</div>`;}
function renderProfile(){const li=levelInfo();return `${title('حكاية تقدّمك','ملف اللاعب','كل إجابة تضيف خطوة إلى رحلتك. يُحفظ التقدم على هذا المتصفح والجهاز.')}<section class="profile-hero panel"><span class="big-avatar">${progress.profile.avatar}</span><div><span class="eyebrow">المستوى ${li.level}</span><h2>${esc(progress.profile.name)}</h2><p class="muted">${num(progress.xp)} خبرة · ${num(li.left)} للمستوى التالي</p><div class="meter"><span style="width:${li.percent}%"></span></div></div><button class="btn secondary" data-action="nav" data-route="settings">تعديل الملف ${icon('user')}</button></section><div class="stats-grid">${stat('cup',num(progress.games),'الجولات المكتملة')}${stat('check',`${progress.correct}/${progress.answers}`,'الإجابات الصحيحة')}${stat('bolt',num(progress.bestStreak),'أفضل سلسلة')}${stat('star',num(progress.points),'إجمالي النقاط')}</div><div class="panel row"><span>انتصارات: <strong>${progress.wins}</strong></span><span>خسائر: <strong>${progress.losses}</strong></span><small class="muted">الفردي: دقة 60% للفوز. المتعدد: صدارة اللاعب الأول. التدريب مستثنى.</small></div><div class="section-heading"><h2>أوسمة تستحقها</h2><span class="muted">${progress.achievements.length} من ${ACHIEVEMENTS.length}</span></div><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<div class="achievement-card ${progress.achievements.includes(a.id)?'':'locked'}"><span class="mode-icon">${icon(a.icon)}</span><h3>${a.name}</h3><p>${a.desc}</p><span class="badge">${progress.achievements.includes(a.id)?'تم الإنجاز':'قيد التقدم'}</span></div>`).join('')}</div><div class="section-heading"><h2>بصمتك في كل فئة</h2><button class="text-btn" data-action="nav" data-route="history">سجل الأسئلة ${icon('history')}</button></div><div class="grid-2">${CATEGORIES.map(c=>{const st=progress.category[c.id]||{answered:0,correct:0},mastery=Math.min(100,Math.round(QUESTION_BANK.filter(q=>q.category===c.id&&progress.solved[q.id]).length/QUESTION_BANK.filter(q=>q.category===c.id).length*100));return `<div class="panel mastery-card"><div class="row"><span class="stat-icon" style="color:${c.color}">${icon(c.icon)}</span><h3>${c.name}</h3><strong>${mastery}%</strong></div><div class="meter"><span style="width:${mastery}%;background:${c.color}"></span></div><p class="muted">${st.correct} صحيحة من ${st.answered} محاولة · الإتقان يقيس الأسئلة المختلفة التي أجبت عنها بشكل صحيح</p></div>`;}).join('')}</div><div class="section-heading"><h2>أرقامك القياسية</h2></div><div class="grid-3">${[...MODES,modeById('daily')].filter(m=>progress.records[m.id]!==undefined).map(m=>`<div class="panel"><h3>${m.name}</h3><strong class="record-number">${num(progress.records[m.id])}</strong><small class="muted"> نقطة · مجموع الجولة لكل اللاعبين</small></div>`).join('')||'<p class="muted">أكمل جولتك الأولى لتبدأ سجل أرقامك.</p>'}</div>${window.SeenTeamUI?.profileAddon()||''}`;}
function renderHistory(){return `${title('كل سؤال يترك أثرًا','سجل الأسئلة','آخر 100 محاولة، مع الإجابات والتفسيرات.')}<button class="text-btn" data-action="nav" data-route="profile">${icon('arrow')} العودة للملف</button><div class="stack">${progress.history.map(h=>{const q=QUESTION_MAP.get(h.id);if(!q)return '';return `<details class="panel review-item"><summary>${icon(h.correct?'check':'close')}<span>${esc(q.q)}</span><span class="badge">${catById(q.category).name}</span></summary><div>${isAnswerProtected(q.id)?'<p class="muted">الإجابة محجوبة حتى حسم هذا السؤال في الجولة الجارية.</p>':`<strong>${esc(q.options[q.answer])}</strong><p>${esc(q.explanation)}</p><a class="source-link" href="${esc(safeURL(q.source.url))}" target="_blank" rel="noopener noreferrer">${esc(q.source.title)} · ${esc(q.source.reference)}</a>`}</div></details>`;}).join('')||'<div class="panel empty-state">ستجد هنا الأسئلة بعد أول محاولة.</div>'}</div>`;}
function selectPref(id,label,options){return `<div class="field"><label for="pref-${id}">${label}</label><select id="pref-${id}" data-pref="${id}">${options.map(([value,text,disabled])=>`<option value="${value}" ${String(prefs[id])===String(value)?'selected':''} ${disabled?'disabled':''}>${text}</option>`).join('')}</select></div>`;}
function togglePref(id,label){return `<label class="toggle-row" for="pref-${id}"><span>${label}</span><input id="pref-${id}" type="checkbox" data-pref="${id}" ${prefs[id]?'checked':''}></label>`;}
function renderSettings(){return `${title('راحتك أولًا','الإعدادات','خصّص تجربتك. تُطبّق إعدادات المؤقّت والصعوبة على الأسئلة الجديدة.')}<div class="settings-grid"><section class="panel stack"><h2>${icon('user')} هويتك في اللعبة</h2><div class="field"><label for="nickname">اسم اللاعب</label><input id="nickname" value="${esc(progress.profile.name)}" maxlength="24" autocomplete="nickname" data-profile="name"></div><span>الصورة الرمزية</span><div class="avatar-grid">${AVATARS.map(a=>`<button class="avatar ${progress.profile.avatar===a?'selected':''}" data-action="avatar" data-value="${a}" aria-label="صورة رمزية ${a}" aria-pressed="${progress.profile.avatar===a}">${a}</button>`).join('')}</div><span>فئاتك المفضلة</span><div class="chips">${CATEGORIES.map(c=>`<button class="chip ${progress.profile.favorites.includes(c.id)?'selected':''}" data-action="favorite" data-id="${c.id}" aria-pressed="${progress.profile.favorites.includes(c.id)}">${c.name}</button>`).join('')}</div></section>
<section class="panel stack"><h2>${icon('spark')} العرض والحركة</h2>${selectPref('theme','المظهر',[['dark','ليلي'],['light','نهاري']])}${selectPref('accent','اللمسة اللونية',[['violet','البنفسجي الملكي'],['gold',progress.xp>=400?'الذهبي · مفتوح':'الذهبي · يُفتح عند المستوى 3',progress.xp<400]])}${selectPref('textSize','حجم النص',[[90,'90%'],[100,'100%'],[115,'115%'],[130,'130%']])}${selectPref('motion','كثافة الحركة',[['none','متوقفة'],['subtle','هادئة'],['full','كاملة']])}${togglePref('reduced','تقليل الحركة دائمًا')}${togglePref('images','عرض الصور المحلية')}<small class="muted">يُحترم خيار تقليل الحركة في نظام الجهاز تلقائيًا. لا تُحمّل أي صور من الإنترنت.</small></section>
<section class="panel stack"><h2>${icon('sound')} الصوت والموسيقى</h2><div class="field"><label for="pref-sound">المؤثرات الصوتية <output>${prefs.sound}%</output></label><input id="pref-sound" type="range" min="0" max="100" data-pref="sound" value="${prefs.sound}"></div><div class="field"><label for="pref-music">الموسيقى الهادئة <output>${prefs.music}%</output></label><input id="pref-music" type="range" min="0" max="100" data-pref="music" value="${prefs.music}"></div><button class="btn secondary" data-action="test-sound">تجربة الصوت ${icon('sound')}</button><small class="muted">الموسيقى والمؤثرات ألحان توليدية أصلية داخل اللعبة، بلا ملفات خارجية. يبدأ الصوت بعد تفاعلك مع الصفحة.</small></section>
<section class="panel stack"><h2>${icon('clock')} قواعد اللعب</h2>${togglePref('timer','تفعيل مؤقّت الأسئلة')}${selectPref('duration','زمن السؤال',[[15,'15 ثانية'],[20,'20 ثانية'],[30,'30 ثانية'],[45,'45 ثانية'],[60,'60 ثانية']])}${selectPref('difficulty','الصعوبة المفضلة',[['adaptive','متدرجة حسب الأداء'],['1','سهل'],['2','متوسط'],['3','صعب'],['4','خبير']])}${togglePref('spoilers','تطبيق مستويات حرق الأنمي المحددة')}${animePreferences()}${selectPref('repetition','تكرار الأسئلة',[['recent','تجنب الأسئلة الحديثة'],['unseen','تفضيل غير المشاهد'],['all','السماح بالجميع']])}<small class="muted">التحدي السريع: 12 ثانية دائمًا. التدريب بلا مؤقّت. الصعوبة المتدرجة تبدأ سهلة وترتفع كل 4 أسئلة؛ تزيد مع السلاسل وتنخفض عند دقة أقل من 40%.</small></section>
<section class="panel stack"><h2>${icon('shield')} الحفظ والخصوصية</h2><p class="muted">${storageAvailable?'يُحفظ تقدمك محليًا. لا حسابات ولا تتبّع.':'التخزين المحلي غير متاح حاليًا. صدّر تقدمك قبل إغلاق الصفحة.'} قد تختلف مساحة الحفظ بين فتح الملف مباشرة وفتحه من رابط.</p>${soloRecovery?'<p class="muted">تعذّرت استعادة الجولة السابقة بأمان. بقيت نسخة خام محفوظة للمراجعة. يتاح تصديرها قبل بدء جولة جديدة أو بعد اكتمال جميع الجولات الجارية لحماية الحلول. لا يُمسح تقدمك الآخر.</p><button class="btn secondary" data-action="solo-recovery">تصدير نسخة الحفظ السابقة</button>':''}<button class="btn secondary" data-action="export">تصدير التقدم ${icon('download')}</button><button class="btn secondary" data-action="import">استيراد تقدم أو جولة ${icon('upload')}</button><button class="btn secondary" data-action="paste-save">استيراد من نص</button><button class="btn secondary" data-action="solo-export" ${session?'':'disabled'}>تصدير الجولة المحفوظة ${icon('download')}</button><p class="muted">تصدير التقدم يشمل ملفك وإعداداتك وإحصاءاتك فقط. نسخة الاستئناف تشمل الجولة المتوقفة والأسئلة المحلية اللازمة، وهي خاصة بالمقدم. عند تعذر الحفظ التلقائي نزّلها قبل إغلاق الصفحة.</p><button class="btn secondary" data-action="reset-seen">بدء دورة جديدة للأسئلة</button><p class="muted">يسمح بإعادة الأسئلة السابقة دون حذف النتائج أو الإنجازات أو سجل المباريات.</p><button class="btn danger" data-action="reset">تصفير التقدم الفردي</button></section><section class="panel stack"><h2>${icon('help')} حول التجربة</h2><button class="btn secondary" data-action="help">دليل اللعب والمفاتيح</button><button class="btn secondary" data-action="about">المحتوى والمراجع والتراخيص</button><button class="btn secondary" data-action="fullscreen">ملء الشاشة ${icon('expand')}</button><p class="muted">يعمل الملف محليًا دون تثبيت أو خادم. الشاشة الكاملة حسب دعم متصفحك. لا تتغير الجولة عند تدوير الجهاز.</p></section></div>`;}
function openDialog(heading,body,actions=''){lastFocus=document.activeElement;const d=$('#dialog');d.innerHTML=`<div class="modal"><div class="dialog-head"><h2>${heading}</h2><button class="icon-btn" data-action="close-dialog" aria-label="إغلاق">${icon('close')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;if(!d.open)d.showModal();d.querySelector('button, input')?.focus();}
function closeDialog(){if(storageConflict)return;const d=$('#dialog');if(d.open)d.close();lastFocus?.focus?.();}
function showHelp(){if(!['play','setup','result'].includes(route)&&window.SeenTeamUI?.ready()){window.SeenTeamUI.rules();return;}pauseSession();if(route==='play')render();openDialog('دليل اللعب',`<div class="stack"><p>اختر نمط اللعب والفئات، ثم اعتمد إجابتك. يظهر التفسير والمصدر بعد الإجابة. لا تتكرر الأسئلة داخل الجولة، وتُفضَّل الأسئلة التي لم تجب عنها في الجولات الجديدة.</p><p><strong>النقاط:</strong> 100 × مستوى الصعوبة، أو قيمة خانة اللوحة. كل إجابتين متتاليتين بعد الأولى تضيفان 50 نقطة، بحد 250. مضاعفة النقاط تضاعف المجموع. التدريب دون نقاط؛ الإجابة الصحيحة فيه تمنح 5 خبرة.</p><p><strong>الحفظ:</strong> يُحفظ كل جواب تلقائيًا. العودة للرئيسية أو إخفاء الصفحة يوقفان مؤقّت السؤال. استأنف من بطاقة الجولة المحفوظة.</p><p><strong>التحدي اليومي:</strong> حتى 10 أسئلة متاحة بلا حرق؛ يظهر العدد الفعلي قبل البدء. تتحدد الأسئلة بتاريخ الجهاز المحلي عند بدء الجولة. يبقى تاريخ الجولة ثابتًا حتى لو أكملتها بعد منتصف الليل، ولا تُمسح الأيام السابقة.</p><p><strong>المتعدد:</strong> التناوب على الجهاز نفسه، مع مساعدات مستقلة لكل لاعب. الإحصاءات في الملف تجمع محاولات جميع المشاركين.</p><p><strong>المفاتيح:</strong> الأرقام 1 إلى 4 للاختيارات، Enter للسؤال التالي بعد الكشف، وEscape لإيقاف السؤال. التنقل بـTab والاعتماد بـEnter أو المسافة.</p><p><strong>الإجابات الكتابية:</strong> تطابق الاسم الكامل بعد إزالة التشكيل وتوحيد الهمزات والمسافات. لا تستخدم تخمينًا لغويًا أو خدمة ذكاء اصطناعي.</p><p>تحدي الصور في هذا الإصدار مخصّص للأعلام والخرائط وصور المعالم والملاعب والآثار والأجهزة. لا يتضمن صور شخصيات أنمي أو لاعبين أو شعارات أندية مرخّصة حتى الآن.</p></div>`);}
function showAbout(){pauseSession();if(route==='play')render();openDialog('سين جيم خالد · المحتوى والتراخيص',`<div class="stack"><p>الإصدار 3 · ${QUESTION_BANK.length} سؤالًا مكتملًا، موزعة على 8 فئات.</p><p>البنك يتوسع بإضافات موثقة مع الحفاظ على الأسئلة السابقة. صور التعرف على الشخصيات واللاعبين وشعارات الأندية غير مدرجة في هذا الإصدار؛ تحدي الصور يشمل أعلامًا وخرائط فعلية وصورًا مرخصة لمعالم وملاعب وآثار وأجهزة.</p><p>تتضمن الأسئلة مراجع للتتبّع والمراجعة. جرت مراجعة تحريرية ومطابقة لمصادر مختارة، وليست اعتمادًا أكاديميًا أو شرعيًا مستقلًا لكل سؤال. في الروايات الجاهلية نستخدم صياغة مقيّدة عندما تكون الأخبار أدبية أو مختلفًا فيها.</p><div class="grid-2">${CATEGORIES.map(c=>`<div><strong>${c.name}</strong><p class="muted">${QUESTION_BANK.filter(q=>q.category===c.id).length} سؤالًا</p></div>`).join('')}</div><p>رسوم الفئات والأعلام أصلية. خرائط الدول من Natural Earth ذات الملكية العامة، والصور الفوتوغرافية من مصادر مرخصة موضحة عند الكشف. رسوم الفئات رمزية وليست صورًا لشخصيات أو مواقع تاريخية بعينها. بعض الأعلام ذات الشعارات رُسمت بصورة مبسّطة، ويُذكر ذلك في وصف الصورة. لا توجد صور للأنبياء.</p><p>الرسوم والمؤثرات والموسيقى الأصلية متاحة وفق CC0-1.0. الأعلام رموز وطنية مستخدمة للتعليم؛ قد يخضع استخدامها خارج اللعبة لقواعد البلد المعني. أسماء الأعمال والعلامات لأصحابها.</p><p>خط Noto Sans Arabic مرخّص وفق SIL Open Font License 1.1. الخط مضمّن للعمل دون اتصال.</p><details><summary>رخصة الخط</summary><pre class="license-text" dir="ltr">${esc(FONT_LICENSE)}</pre></details><p>لفتح اللعبة دون إنترنت: احفظ ملف index.html وافتحه في متصفحك. لا توجد أصول مطلوبة خارجه، ولا حاجة إلى عامل خدمة.</p></div>`);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('الشاشة الكاملة غير متاحة هنا. يمكنك اللعب بالعرض الحالي.');}catch{toast('تعذّر تفعيل ملء الشاشة. اللعبة متاحة بالعرض الحالي.');}}
function downloadLocalSave(data,filename){
const text=typeof data==='string'?data:JSON.stringify(data,null,2);
try{
const a=document.createElement('a');
if(typeof Blob!=='function'||typeof URL.createObjectURL!=='function'||!('download'in a))throw Error();
const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);return true;
}catch{
openDialog('نسخة حفظ يدوية',`<p>هذا المتصفح لا يتيح التنزيل المباشر هنا. انسخ النص واحتفظ به خارج اللعبة، ثم استخدم «استيراد من نص» لاستعادته. ويمكن حفظه في ملف باسم <b dir="ltr">${esc(filename)}</b>.</p><label for="manual-save-text">بيانات نسخة الحفظ</label><textarea id="manual-save-text" dir="ltr" readonly spellcheck="false">${esc(text)}</textarea>`,'<button class="btn primary" data-action="copy-save">نسخ بيانات الحفظ</button>');return false;
}
}
async function copyManualSave(){const input=$('#manual-save-text');if(!input)return;input.focus();input.select();try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(input.value);toast('نُسخت بيانات الحفظ. احتفظ بها خارج اللعبة لاستيرادها لاحقًا.');}catch{toast('النص محدد؛ اضغط مطولًا واختر نسخ، ثم احتفظ به خارج اللعبة.');}}
function pasteLocalSave(onFile){
if(typeof onFile!=='function')return;
pauseSession();openDialog('استيراد من نص','<p>الصق بيانات نسخة الحفظ التي صدّرتها اللعبة. تُفحص البيانات قبل عرض تأكيد الاستيراد؛ تبقى جولتك الحالية محفوظة حتى تعتمد النسخة.</p><label for="paste-save-text">بيانات نسخة الحفظ</label><textarea id="paste-save-text" dir="ltr" spellcheck="false" autocapitalize="off" autocomplete="off"></textarea>','<button class="btn primary" id="prepare-pasted-save">فحص النسخة</button><button class="btn secondary" data-action="close-dialog">إلغاء</button>');
const input=$('#paste-save-text'),button=$('#prepare-pasted-save');input.focus();let pending=false;
button.addEventListener('click',async()=>{if(pending)return;const text=input.value;if(!text.trim()){toast('الصق بيانات نسخة الحفظ أولًا.');input.focus();return;}if(text.length>28100000){toast('بيانات الحفظ أكبر من الحجم المسموح.');return;}const size=new TextEncoder().encode(text).length;if(size>28100000){toast('بيانات الحفظ أكبر من الحجم المسموح.');return;}pending=true;button.disabled=true;try{await onFile({name:'seen-pasted-save.json',size,text:async()=>text});}catch{toast('تعذّر استيراد النص. تبقى الجولة الحالية دون تغيير.');}finally{pending=false;if(button.isConnected)button.disabled=false;}});
}
function exportProgress(){pauseSession();persist();if(downloadLocalSave({version:1,prefs,progress},`seen-khaled-${localDate()}.json`))toast('أُعدّت نسخة تقدمك للتنزيل.');}
function portableSoloSession(value){if(!value)return null;const out=JSON.parse(JSON.stringify(value));if(out.current?.phase==='answer'){const c=out.current;if(c.deadline!==null)c.remainingMs=clamp(c.deadline-Date.now(),0,180000);c.deadline=null;c.paused=true;}return out;}
function exportSoloRound(){
if(!session){toast('لا توجد جولة محفوظة لتصديرها.');return;}
pauseSession();persist();
try{const owner=window.SeenTeamUI?.store,library=owner?{edits:owner.edits,disabled:owner.disabled}:undefined;const data={version:1,prefs,progress,session:portableSoloSession(session),...(library?{library}:{})};if(downloadLocalSave(encodeMatchBackup('solo',data),`seen-solo-resume-${localDate()}.json`))toast('أُعدّت نسخة استئناف الجولة للمقدم. احتفظ بها قبل إغلاق الصفحة.');}catch(e){toast(/[\u0600-\u06ff]/.test(e.message)?e.message:'تعذّر إعداد نسخة الاستئناف. تبقى الجولة مفتوحة.');}
if(route==='play')render();
}
function prepareSoloResume(raw){
const data=decodeMatchBackup(raw,'solo');let library=null,questionMap=QUESTION_MAP;
if(data.library!==undefined){if(!window.SeenTeamUI?.prepareResumeLibrary)throw Error('تعذّرت تهيئة مكتبة الأسئلة. أعد المحاولة بعد اكتمال تحميل اللعبة.');library=window.SeenTeamUI.prepareResumeLibrary(data.library);questionMap=new Map(library.questions.map(q=>[q.id,q]));}
const checked=validateSave(data,true,questionMap);
if(data.session&&!checked.session)throw Error('تعذّرت استعادة الجولة بأمان. بقي تقدمك والجولة الحالية دون تغيير.');
checked.session=portableSoloSession(checked.session);return {checked,library};
}
async function importFile(file){
if(!file)return;
try{
if(file.size>28100000)throw Error('ملف الحفظ أكبر من الحجم المسموح.');
const raw=parseSafeJSON(await file.text(),28100000),resume=raw.format==='seen-khaled-resume';
if(!resume&&file.size>1500000)throw Error('ملف التقدم أكبر من الحجم المسموح.');
if(resume&&raw.kind!=='solo')throw Error('هذه نسخة مباراة فريقين. استوردها من حفظ الفريقين في سجل المباريات.');
const prepared=resume?prepareSoloResume(raw):{checked:validateSave(raw),library:null},checked=prepared.checked;
pauseSession();
openDialog(resume?'استئناف الجولة من النسخة؟':'استبدال التقدم المحفوظ؟',`<p>الملف باسم <strong>${esc(checked.progress.profile.name)}</strong> ويحتوي على ${checked.progress.answers} محاولة و${checked.progress.games} جولات. ${resume?'تُستعاد الجولة متوقفة مع ترتيب أسئلتها ومساعداتها، وتحل محل الجولة الفردية الحالية.':'سيحل محل تقدمك الفردي الحالي والجولة الجارية.'} تبقى مباريات الفريقين وسجلاتها محفوظة.</p>`,'<button class="btn primary" id="confirm-import">استيراد النسخة</button><button class="btn secondary" data-action="close-dialog">إلغاء</button>');
$('#confirm-import').addEventListener('click',()=>{
if(prepared.library)window.SeenTeamUI.commitResumeLibrary(prepared.library);
progress=checked.progress;prefs=checked.prefs;session=checked.session;soloRecoveryProtected=false;applyPrefs();const saved=persist();closeDialog();navigate(resume&&session?'play':'profile');toast(saved?'تم استيراد الحفظ بنجاح.':'استُعيد الحفظ في هذه الصفحة. التخزين التلقائي غير متاح؛ احتفظ بنسخة الاستئناف.');
},{once:true});
}catch(e){toast(e instanceof SyntaxError?'تعذّرت قراءة الملف. اختر ملف حفظ صالحًا.':/[\u0600-\u06ff]/.test(e.message)?e.message:'تعذّر استيراد الحفظ. الملف غير صالح.');}
finally{$('#import-file').value='';}
}
function resetQuestionHistory(){progress.seen={};prefs.questionHistoryResetAt=Date.now();persist();}
function requestQuestionHistoryReset(){pauseSession();openDialog('بدء دورة جديدة للأسئلة؟','<p>ستتوقف تفضيلات التكرار عن احتساب الأسئلة السابقة، فيمكن ظهورها مجددًا في المباريات والجولات الجديدة. لا تُحذف النتائج أو الإنجازات أو الأسئلة المعدلة أو سجل الإجابات والمباريات، ولا تتغير لوحة المباراة الجارية.</p>','<button class="btn primary" id="confirm-reset-seen">ابدأ دورة جديدة</button><button class="btn secondary" data-action="close-dialog">إلغاء</button>');$('#confirm-reset-seen').addEventListener('click',()=>{resetQuestionHistory();closeDialog();render();toast('بدأت دورة جديدة للأسئلة. بقيت نتائجك وسجلاتك محفوظة.');},{once:true});}
function requestStart(mode,daily=false){if(session?.status==='active'){pauseSession();openDialog('لديك جولة محفوظة',`<p>بدء جولة جديدة سيستبدل الجولة الجارية. تبقى إجاباتك السابقة وخبرتك محفوظتين.</p>`,`<button class="btn primary" id="confirm-start">بدء جولة جديدة</button><button class="btn secondary" data-action="resume-dialog">متابعة المحفوظة</button>`);$('#confirm-start').addEventListener('click',()=>{closeDialog();startGame(mode,daily);},{once:true});}else startGame(mode,daily);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;if(b.dataset.action==='reload'){window.location.reload();return;}if(storageConflict)return;unlockAudio();sound('click');const action=b.dataset.action;
if(action==='nav')navigate(b.dataset.route);
else if(action==='solo-anime-all'||action==='solo-anime-none'){prefs.anime={...prefs.anime,selected:action==='solo-anime-all'?TeamEngine.FRANCHISES.map(f=>f.id):[]};persist();render();}
else if(action==='solo-recovery'&&soloRecovery){if(hasActiveTrivia()){toast('تبقى نسخة الاسترداد محفوظة كما هي. يتاح تصديرها بعد اكتمال الجولة أو المباراة الجارية لحماية الحلول.');return;}downloadLocalSave(soloRecovery,`seen-recovery-${localDate()}.json`);}
else if(action==='setup'){if(b.dataset.mode==='classic'&&window.SeenTeamUI)window.SeenTeamUI.startSetup();else makeSetup(b.dataset.mode);}
else if(action==='browse-category')makeSetup('solo',[b.dataset.id]);
else if(action==='toggle-category'){const id=b.dataset.id;if(setup.cats.includes(id))setup.cats=setup.cats.filter(x=>x!==id);else setup.cats.push(id);render();}
else if(action==='start')requestStart(setup.mode);
else if(action==='daily'){if(progress.daily[localDate()]?.completed)return;if(session?.status==='active'&&session.mode==='daily'&&session.date===localDate()){resumeGame();return;}setup={mode:'daily',players:1,names:[progress.profile.name],cats:CATEGORIES.map(c=>c.id),format:'choice',series:'all'};requestStart('daily',true);}
else if(action==='resume')resumeGame();
else if(action==='resume-dialog'){closeDialog();resumeGame();}
else if(action==='ready'){session.handoff=false;if(session.mode!=='classic')nextQuestion();persist();render();}
else if(action==='tile'){const tile=session?.board.find(t=>t.key===b.dataset.key);if(tile&&!tile.done&&!session.current){nextQuestion(tile);render();window.scrollTo(0,0);}}
else if(action==='answer')commitAnswer(Number(b.dataset.index));
else if(action==='next')goNext();
else if(action==='helper')helper(b.dataset.helper);
else if(action==='pause'){pauseSession();render();}
else if(action==='unpause')resumeQuestion();
else if(action==='close-dialog')closeDialog();
else if(action==='helper-rules'){pauseSession();render();openDialog('قواعد المساعدات',`<div class="stack">${HELPERS.map(h=>`<p><strong>${h.name}:</strong> ${h.desc}</p>`).join('')}<p class="muted">المساعدات تتجدد في كل جولة. لكل لاعب في التحديات المحلية رصيد مستقل. فتح الدليل يوقف السؤال، وتحتاج إلى استئنافه بعد الإغلاق.</p></div>`);}
else if(action==='zoom'){const img=VISUALS[b.dataset.image];if(img){pauseSession();render();openDialog('الصورة بحجم أكبر',`<img class="zoom-image" src="${imageSrc(b.dataset.image)}" alt="${esc(session?.current?.phase==='feedback'?img.alt:'دليل بصري للسؤال؛ الوصف التعريفي متاح بعد الإجابة.')}">${session?.current?.phase==='feedback'?(window.SeenTeamUI?.mediaCredit(b.dataset.image)||''):'<p class="muted">الإسناد والرخصة متاحان بعد الإجابة.</p>'}`);}}
else if(action==='enable-images'){prefs.images=true;applyPrefs();persist();render();}
else if(action==='theme'){prefs.theme=prefs.theme==='dark'?'light':'dark';applyPrefs();persist();render();}
else if(action==='fullscreen')fullscreen();
else if(action==='avatar'){progress.profile.avatar=b.dataset.value;persist();render();}
else if(action==='favorite'){const id=b.dataset.id;progress.profile.favorites=progress.profile.favorites.includes(id)?progress.profile.favorites.filter(x=>x!==id):[...progress.profile.favorites,id];persist();render();}
else if(action==='test-sound'){sound('correct');ambient();}
else if(action==='help')showHelp();
else if(action==='about')showAbout();
else if(action==='export')exportProgress();
else if(action==='solo-export')exportSoloRound();
else if(action==='copy-save')copyManualSave();
else if(action==='paste-save')pasteLocalSave(importFile);
else if(action==='reset-seen')requestQuestionHistoryReset();
else if(action==='import'){$('#import-file').click();}
else if(action==='reset'){pauseSession();openDialog('تصفير التقدم؟','<p>ستُحذف إحصاءات اللعب الفردي وإنجازاته وجولته المحفوظة من هذا المتصفح. لا يؤثر ذلك في مباريات الفريقين أو الأسئلة المعدلة. يمكنك تصدير نسخة قبل المتابعة. يبقى المظهر والصوت كما اخترتهما.</p>','<button class="btn danger" id="confirm-reset">نعم، احذف التقدم</button><button class="btn secondary" data-action="close-dialog">إلغاء</button>');$('#confirm-reset').addEventListener('click',()=>{progress=freshProgress();session=null;persist();closeDialog();navigate('home');toast('تم تصفير التقدم.');},{once:true});}
else if(action==='replay'){if(session.mode==='daily'){toast('اكتمل تحدي اليوم. جرّب التدريب أو عد غدًا.');makeSetup('practice',session.cats);}else makeSetup(session.mode,session.cats);}
});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-solo-anime]')){const selected=new Set(prefs.anime.selected);if(t.checked)selected.add(t.dataset.soloAnime);else selected.delete(t.dataset.soloAnime);prefs.anime={...prefs.anime,selected:[...selected]};persist();render();}else if(t.matches('[data-solo-spoiler]')){prefs.anime={...prefs.anime,levels:{...prefs.anime.levels,[t.dataset.soloSpoiler]:Number(t.value)}};prefs.spoilers=true;persist();render();}else if(t.matches('[data-pref]')){const k=t.dataset.pref;if(k==='accent'&&t.value==='gold'&&progress.xp<400)return;prefs[k]=t.type==='checkbox'?t.checked:['sound','music','duration','textSize'].includes(k)?Number(t.value):t.value;applyPrefs();persist();unlockAudio();render();}else if(t.matches('[data-profile]')){progress.profile.name=cleanName(t.value);persist();shell();t.value=progress.profile.name;}else if(t.matches('[data-setup]')){setup[t.dataset.setup]=t.dataset.setup==='players'?Number(t.value):t.value;render();}else if(t.matches('[data-player]'))setup.names[Number(t.dataset.player)]=cleanName(t.value,`اللاعب ${Number(t.dataset.player)+1}`);else if(t.id==='import-file')importFile(t.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='text-answer'){e.preventDefault();commitAnswer(new FormData(e.target).get('answer'));}});
document.addEventListener('keydown',e=>{if($('#dialog').open||e.target.matches('input,textarea,select'))return;if(route==='play'&&session?.current){const c=session.current;if(e.key==='Escape'&&c.phase==='answer'){e.preventDefault();pauseSession();render();}else if(e.key==='Enter'&&c.phase==='feedback'&&!e.target.closest('button,a,summary')){e.preventDefault();goNext();}else if(/^[1-4]$/.test(e.key)&&c.phase==='answer'&&!c.paused&&c.format!=='text'){const idx=Number(e.key)-1,order=c.format==='boolean'?[1,0]:c.order;if(idx<order.length){e.preventDefault();unlockAudio();commitAnswer(order[idx]);}}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseSession();stopMusic();if(route==='play')render();}else if(audioContext?.state==='running'&&prefs.music){ambient();musicHandle=setInterval(ambient,6000);}});
